    mh_output.count = 0U;
    mh_output.rejected = 0U;
    mh_output.bias = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_output.half_span = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}

