if (mh_state.mode != MH_COLLECT) {
    mh_state.minimum = *mh_input.sample;
    mh_state.maximum = *mh_input.sample;
    mh_state.count = 1U;
    mh_state.mode = MH_COLLECT;
} else {
    if (mh_input.sample->x > mh_state.maximum.x) mh_state.maximum.x = mh_input.sample->x;
    if (mh_input.sample->y > mh_state.maximum.y) mh_state.maximum.y = mh_input.sample->y;
    if (mh_input.sample->z > mh_state.maximum.z) mh_state.maximum.z = mh_input.sample->z;
    if (mh_input.sample->x < mh_state.minimum.x) mh_state.minimum.x = mh_input.sample->x;
