    bias.y = 0.5 * (mh_state.maximum.y + mh_state.minimum.y);
    bias.z = 0.5 * (mh_state.maximum.z + mh_state.minimum.z);
    half_x = 0.5 * (mh_state.maximum.x - mh_state.minimum.x);
    half_y = 0.5 * (mh_state.maximum.y - mh_state.minimum.y);
    half_z = 0.5 * (mh_state.maximum.z - mh_state.minimum.z);
    half_span = (adcs_vec3_t){half_x, half_y, half_z};

    all_ok = 1;
    if (half_x < mh_config.minimum_span) all_ok = 0;
    if (half_y < mh_config.minimum_span) all_ok = 0;
    if (half_z < mh_config.minimum_span) all_ok = 0;

    if (all_ok) {
        mh_state.mode = MH_READY;
        mh_state.bias = bias;
        mh_state.rejected = 0U;
        mh_output.mode = MH_READY;
        mh_output.count = mh_state.count;
        mh_output.rejected = 0U;
        mh_output.bias = bias;
        mh_output.half_span = half_span;
        mh_output.span_norm = adcs_vec3_norm(&half_span);
        mh_output.span_energy = adcs_vec3_dot(&half_span, &half_span);
        return;
    }

    /* insufficient excitation：已到达非零上限则闩锁 FAULT */
    if ((mh_config.max_rejected_windows != 0U) &&
        (mh_state.rejected >= mh_config.max_rejected_windows)) {
        mh_state.rejected++;
        mh_state.mode = MH_FAULT;
        mh_output.mode = MH_FAULT;
        mh_output.count = mh_state.count;
        mh_output.rejected = mh_state.rejected;
        return;
    }

    /* 否则重启采集并累加 rejected */
    mh_state.rejected++;
    mh_state.count = 0U;
    mh_state.mode = MH_IDLE;
    mh_state.minimum = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_state.maximum = (adcs_vec3_t){0.0, 0.0, 0.0};
}

/* 子过程6：输出同步（未完成窗口的正常路径） */
